-- =============================================================================
-- 0037 — Statutory payroll contribution schedules: EPF, SOCSO and EIS
--
-- Rule 7: statutory values are effective-dated DATA, never hardcoded constants.
-- These are the published schedules themselves, transcribed from the legal
-- instruments and committed under docs/research/sources/ so any figure here can
-- be traced back to the page it came from.
--
-- -----------------------------------------------------------------------------
-- WHY TABLES AND NOT PERCENTAGES.
--
-- All three schemes are lookup tables in law. EPF's Third Schedule fixes the
-- exact ringgit amount for every wage band up to RM20,000; SOCSO and EIS do the
-- same up to their RM6,000 ceiling. Multiplying a percentage produces a figure
-- that is close and wrong — a few sen out on most salaries — and an
-- under-deduction of a statutory contribution is the EMPLOYER's liability.
-- The percentages people quote are descriptions of these tables, not the rule.
--
-- -----------------------------------------------------------------------------
-- THESE TABLES ARE GLOBAL, NOT TENANT-OWNED.
--
-- The rates are national. Every tenant reads the same rows, nobody writes them
-- except a migration, and the application role gets SELECT only. They are
-- therefore RLS-exempt for the same reason `einvoice_classification_code` and
-- `report_template` are, and are listed with that reason in rls.test.ts and
-- audit.test.ts rather than silently skipped.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- EPF — Employees Provident Fund Act 1991, Third Schedule.
--
-- `part` is the Schedule's own Part letter, because the Part IS the rule: which
-- one applies depends on age and citizenship, and naming it here keeps the
-- lookup honest to the source. Parts B and D were deleted by Act A1760/2025 and
-- are absent on purpose. Part F is a flat percentage with no bands, so it lives
-- only in the rule table below.
-- ---------------------------------------------------------------------------
CREATE TABLE statutory_epf_band (
    part           TEXT NOT NULL CHECK (part IN ('A','C','E')),
    effective_from DATE NOT NULL,
    wage_from      NUMERIC(19,4) NOT NULL CHECK (wage_from >= 0),
    wage_to        NUMERIC(19,4) NOT NULL CHECK (wage_to > wage_from),
    employer       NUMERIC(19,4) NOT NULL CHECK (employer >= 0),
    employee       NUMERIC(19,4) NOT NULL CHECK (employee >= 0),

    PRIMARY KEY (part, effective_from, wage_from)
);

-- ---------------------------------------------------------------------------
-- What happens ABOVE the banded range, per Part.
--
-- `ceiling` is where the table stops and the percentage starts — RM20,000 for
-- the banded Parts, and NULL for Part F, which is a percentage from the first
-- ringgit. Rates are basis points so they stay exact integers: 11% is 1100, and
-- Part C's 5.5% is 550, which a percentage column with one decimal could not
-- hold without inviting a float.
-- ---------------------------------------------------------------------------
CREATE TABLE statutory_epf_rule (
    part             TEXT NOT NULL CHECK (part IN ('A','C','E','F')),
    effective_from   DATE NOT NULL,
    ceiling          NUMERIC(19,4),
    employer_rate_bp INTEGER NOT NULL CHECK (employer_rate_bp BETWEEN 0 AND 10000),
    employee_rate_bp INTEGER NOT NULL CHECK (employee_rate_bp BETWEEN 0 AND 10000),
    note             TEXT NOT NULL,

    PRIMARY KEY (part, effective_from)
);

-- ---------------------------------------------------------------------------
-- SOCSO — Employees' Social Security Act 1969 (Act 4), including SKBBK.
--
-- The employee side of Category 1 is TWO columns, not one: Invalidity and
-- SKBBK are separate contributions that happen to be collected together. They
-- are stored apart because they are apart in the schedule, and because a
-- payslip that shows one figure for two statutory deductions cannot be
-- reconciled against PERKESO's own statement.
--
-- SKBBK — Skim Kemalangan Bukan Bencana Kerja, the 24-hour non-work accident
-- scheme — took effect 1 June 2026 and applies to BOTH categories. Category 2
-- previously deducted nothing from the employee and now does.
-- ---------------------------------------------------------------------------
CREATE TABLE statutory_socso_band (
    effective_from           DATE NOT NULL,
    wage_from                NUMERIC(19,4) NOT NULL CHECK (wage_from >= 0),
    /* NULL on the final band: "exceeding RM6,000" is unbounded above. */
    wage_to                  NUMERIC(19,4) CHECK (wage_to IS NULL OR wage_to > wage_from),
    cat1_employer            NUMERIC(19,4) NOT NULL CHECK (cat1_employer >= 0),
    cat1_employee_invalidity NUMERIC(19,4) NOT NULL CHECK (cat1_employee_invalidity >= 0),
    cat1_employee_skbbk      NUMERIC(19,4) NOT NULL CHECK (cat1_employee_skbbk >= 0),
    cat2_employer            NUMERIC(19,4) NOT NULL CHECK (cat2_employer >= 0),
    cat2_employee_skbbk      NUMERIC(19,4) NOT NULL CHECK (cat2_employee_skbbk >= 0),

    PRIMARY KEY (effective_from, wage_from)
);

-- ---------------------------------------------------------------------------
-- EIS — Employment Insurance System Act 2017 (Act 800), Second Schedule.
-- Employer and employee pay the same amount in every band.
-- ---------------------------------------------------------------------------
CREATE TABLE statutory_eis_band (
    effective_from DATE NOT NULL,
    wage_from      NUMERIC(19,4) NOT NULL CHECK (wage_from >= 0),
    wage_to        NUMERIC(19,4) CHECK (wage_to IS NULL OR wage_to > wage_from),
    employer       NUMERIC(19,4) NOT NULL CHECK (employer >= 0),
    employee       NUMERIC(19,4) NOT NULL CHECK (employee >= 0),

    PRIMARY KEY (effective_from, wage_from)
);

GRANT SELECT ON statutory_epf_band, statutory_epf_rule,
                statutory_socso_band, statutory_eis_band TO emil_app;
GRANT SELECT ON statutory_epf_band, statutory_epf_rule,
                statutory_socso_band, statutory_eis_band TO emil_worker;


-- EPF Third Schedule, in force from 1 October 2025 — 1203 bands across Parts A, C and E.


-- SOCSO Act 4 including SKBBK, in force from 1 June 2026 — 65 bands.

-- EIS Act 800, ceiling raised to RM6,000 from 1 October 2024 — 65 bands.

-- ---------------------------------------------------------------------------
-- Who may ask what a wage costs.
--
-- A contributions calculation takes a SALARY as its input, and a salary is the
-- most confidential figure in a five-person shop. The route stores nothing, but
-- anyone who can call it can probe "what would RM 3,200 deduct" — harmless —
-- and, more to the point, is being shown a payroll screen. So it gets its own
-- permission rather than borrowing `report.read`, and SALES and TECHNICIAN do
-- not hold it.
--
-- EXTERNAL_AUDITOR does hold it: statutory contribution workings are exactly
-- what an audit asks to see, and the calculator reveals published national
-- rates, not anybody's pay.
-- ---------------------------------------------------------------------------
ON CONFLICT (code) DO NOTHING;

ON CONFLICT DO NOTHING;
